/* ============================================================================
 * C0/93E1  moveStepExecutor()  -- DP = $1D00.  v.NN == WRAM $7E1DNN.
 * This is the CAMERA / screen-coordinate + VRAM tilemap-strip-REDRAW scheduler.
 * It is NOT position-integration and NOT collision-apply (no $62/$64, no 9C5C/9AA1).
 * Called THREE times per controller frame (881E: 8852/8855, 88B9/88BC, 88DD/88E0),
 * each after C0/91AC+9300 build the whole-pixel step counts $1D41-$1D4C.
 * The actual world-position+collision core is the SEPARATE 8A6D/8AB5/8A9E path
 * (9AA1/9AD3/9C37, writes $62/$64) and 9C5C.
 *
 * Inputs:  v.41=-X v.42=+X v.43=+Y v.44=-Y (layer A; note 94DF reads $43, 94AD reads $44)
 *          v.45=-X v.46=+X v.47=-Y v.48=+Y (layer B)
 *          v.49=-X v.4A=+X v.4B=-Y v.4C=+Y (layer C)
 *          $0BC9 (abs): BPL=normal scroll, BMI=wide(32px)/alt scroll
 *          v.35 = upstream edge-already-requested gate (bit1=layerB, bit2=layerC)
 * ==========================================================================*/
void moveStepExecutor(void)                       /* 93E1 */
{
    v.76 = v.77 = v.74 = v.75 = 0;                /* 93E1-93E7 clear redraw-request scratch */

    walkA_Xpos();   /* 93E9 JSR 944B : v.42 +X */
    walkA_Xneg();   /* 93EC JSR 947D : v.41 -X */
    walkA_Ypos();   /* 93EF JSR 94DF : v.43 +Y */
    walkA_Yneg();   /* 93F2 JSR 94AD : v.44 -Y */

    if ((int8_t)v.0BC9 >= 0) {                    /* 93F5 LDA $0BC9; 93F8 BMI -> alt */
        walkB_46();/*950F*/ walkB_45();/*9545*/ walkB_47();/*95AF*/ walkB_48();/*9579*/  /* normal: NO coord bump, redraw-bit only */
    } else {
        walkB_46alt();/*95E3*/ walkB_45alt();/*9619*/ walkB_47alt();/*9683*/ walkB_48alt();/*964D*/ /* wide: bump $12/$14/$16/$18, half-rate ring */
    }                                            /* 9414 */
    walkC_4A();/*96B7*/ walkC_49();/*96ED*/ walkC_4B();/*975F*/ walkC_4C();/*9721*/

    v.78 = v.79 = v.7A = v.7B = 0;                /* 9420-9426 clear strip-built flags */

    if ((int8_t)v.0BC9 >= 0) {                    /* 9428 LDA $0BC9; 942B BMI -> alt */
        redraw_98C1(); redraw_985F(); redraw_97FD(); redraw_979B();   /* 942D-9436 */
    } else {
        redraw_98F2(); redraw_9890(); redraw_982E(); redraw_97CC();   /* 943C-9445 */
    }
    BRL finalizeVramStrips();                     /* 9439 / 9448 -> C0/7F9A */
}

/* ---- layer-A +X walker = C0/944B (the prompt's 944B focus) -------------------
 * Uses STA (= ) to set v.76, since layer-A is the first to touch it this frame. */
void walkA_Xpos(void) {                            /* 944B */
    uint8_t n = v.42; if (n == 0) return;          /* 944B-944F early RTS */
    v.66 = n;                                      /* 9450 loop counter (transient; safe: collision path already ran in 881E body) */
    do {
        v.87 += 1;                                 /* 9452-9456 INX layer-A X ring index (16-bit) */
        uint8_t a = v.93;                          /* 9457 phase */
        if (a == 0x0F) { v.0A++; v.0C++; v.76 = 0x01; a = 0xFF; }  /* 9459-9465 tile edge */
        if (a == 0x07) { v.0A++; v.0C++; v.76 = 0x01; a = 0x07; }  /* 9467-9473 half-tile edge */
        v.93 = a + 1;                              /* 9475-9476 (0xFF->0, 0x07->8) */
    } while (--v.66 != 0);                          /* 9478-947A */
}
/* walkA_Xneg (947D): v.41, DEX v.87, phase v.93: ==0 -> DEC $0C,$0A, v.77=1, a=0x10;
 *                    ==8 -> DEC $0C,$0A, v.77=1, a=8; v.93=a-1.
 * walkA_Ypos (94DF): v.43, INX v.89, phase v.96, edges 0x0F/0x07 -> INC $0E,$10, v.74=1.
 * walkA_Yneg (94AD): v.44, DEX v.89, phase v.96, ==0/==8 -> DEC, v.75=1.            */

/* ---- layer-B NORMAL walkers (BPL): redraw-bit ONLY, gated by v.35; NO coord bump --
 * walkB_46 (950F): v.46, INX v.8B, phase v.94 (0x0F/0x07) -> if !(v.35&2) v.76|=2.
 * walkB_45 (9545): v.45, DEX v.8B, phase v.94 (0/8)       -> if !(v.35&2) v.77|=2.
 * walkB_47 (95AF): v.47, DEX v.8D, phase v.97 (0/8)       -> if !(v.35&2) v.75|=2.
 * walkB_48 (9579): v.48, INX v.8D, phase v.97 (0x0F/0x07) -> if !(v.35&2) v.74|=2. */

/* ---- layer-B ALT walkers (BMI, 32px wide scroll): DO bump coords, half-rate ring --
 * walkB_46alt (95E3): v.46, phase v.94 thresholds 0x1F/0x0F -> INC $12,$14, v.76|=2;
 *                     v.94++; if ((v.94)&1)==0 INX v.8B (ring steps every OTHER pixel).
 * walkB_45alt (9619): v.45, v.94 ==0/==0x10 -> DEC $14,$12, v.77|=2; DEX v.8B half-rate.
 * walkB_47alt (9683): v.47, v.97 ==0/==0x10 -> DEC $16,$18, v.75|=2; DEX v.8D half-rate.
 * walkB_48alt (964D): v.48, v.97 0x1F/0x0F  -> INC $16,$18, v.74|=2; INX v.8D half-rate. */

/* ---- layer-C walkers (gate v.35 bit2; 9721/975F also adjust DMA budget $FB) ------
 * walkC_4A (96B7): v.4A, INX v.8F, phase v.95 (0x0F/0x07) -> if !(v.35&4) v.76|=4.
 * walkC_49 (96ED): v.49, DEX v.8F, phase v.95 (0/8)       -> if !(v.35&4) v.77|=4.
 * walkC_4B (975F): v.4B, v.FB-=4 (DEC x4), DEX v.91, phase v.98 (0/8) -> v.75|=4.
 * walkC_4C (9721): v.4C, v.FB+=4 (INC x4), INX v.91, phase v.98 (0x0F/0x07) -> v.74|=4. */

